-- migration_016_new_questions_sept2026e.sql
-- Batch 5 of new questions from "Questions to add.pdf": spinal cord stimulation
-- mechanism of action (Physiology), dorsal root ganglion (DRG) stimulation
-- (Clinical Pain), and two clinical-statistics MTFs (Physics & Clinical
-- Measurement) covering coefficient of variation / SD / SEM and diagnostic
-- test performance / choice of statistical test.
--
-- The SCS and DRG questions each carry a knowledge box; SCS also has an orange
-- button linking to NICE TA159 and both carry a "relevantReading" list
-- (rendered as a Relevant reading panel beside the scoreboard on reveal). The
-- two statistics questions have no knowledge box. No new categories.
--
-- Safe to run directly in the Supabase SQL Editor. Idempotent (on conflict do
-- nothing) so it can be re-run harmlessly.

insert into questions (id, type, data, status) values ('q_mtf_scs_mechanism_001', 'MTF', '{"dateAdded":"2026-09-07","rotationIndex":94,"stem":"Spinal cord stimulation (SCS) — regarding its mechanism of action:","choices":["Modulation of thalamic relay neurons","Activation of GABAergic interneurons in the dorsal horn","Activation of descending inhibitory pathways","Vasodilatation","Modulation of the anterior cingulate cortex"],"correct":[true,true,true,true,true],"explanation":"<p>Spinal cord stimulation produces analgesia through several complementary mechanisms &mdash; segmental, supraspinal, neurochemical and vascular &mdash; rather than a single unifying pathway. All five stems describe recognised components.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; SCS modulates the activity of thalamic relay neurons, altering the processing and transmission of nociceptive information at a supraspinal level and contributing to a central modulatory effect beyond simple segmental gate control.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; In line with the classical gate control theory, SCS activates large-diameter A&beta; fibres in the dorsal columns, which in turn drive GABAergic inhibitory interneurons in the dorsal horn, suppressing nociceptive transmission from smaller A&delta; and C fibres at the segmental level.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; SCS engages descending inhibitory pathways from supraspinal centres such as the periaqueductal grey and rostroventral medulla, enhancing top-down modulation of spinal nociceptive processing.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; SCS produces vasodilatation in the stimulated segments through antidromic activation of primary afferents and release of vasoactive substances (CGRP, nitric oxide), which underlies its benefit in vascular / ischaemic pain (refractory angina, peripheral vascular disease, critical limb ischaemia).</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Functional imaging shows that SCS modulates activity in the anterior cingulate cortex and other affective pain-processing regions, contributing to changes in the emotional / affective component of pain.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Spinal Cord Stimulation &mdash; Mechanism of Action</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Spinal cord stimulation produces analgesia through several proposed, complementary mechanisms spanning segmental spinal, supraspinal, neurochemical and vascular effects, rather than through a single unifying pathway.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Segmental mechanism &mdash; gate control theory</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Stimulation preferentially activates large-diameter, myelinated A&beta; fibres in the dorsal columns. These conduct bidirectionally: antidromic signals activate GABAergic interneurones in the dorsal horn, releasing GABA that acts on presynaptic and postsynaptic GABA<sub>A</sub> and GABA<sub>B</sub> receptors to inhibit nociceptive transmission carried by smaller A&delta; and C fibres &mdash; the classical gate originally proposed by Melzack and Wall, and the founding rationale for SCS.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Supraspinal mechanisms</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Orthodromic action potentials in A&beta; fibres travel rostrally via the dorsal columns and spinothalamic tract to modulate brainstem sensory nuclei</td></tr><tr><td>Modulation of thalamic relay neurons alters higher-level processing and transmission of nociceptive information</td></tr><tr><td>Engagement of descending inhibitory pathways from the periaqueductal grey and rostroventral medulla provides top-down modulation of dorsal horn transmission</td></tr><tr><td>Functional imaging shows modulation of the anterior cingulate cortex and insula, implicating the emotional / affective dimension of pain, not just the sensory-discriminative component</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Neurochemical mechanisms</div><table style=\"margin:0\"><tr><th>Change</th><th>Effect in the dorsal horn</th></tr><tr><td>Increased</td><td>Release of inhibitory neurotransmitters &mdash; GABA, and (via descending pathways) serotonin and noradrenaline</td></tr><tr><td>Decreased</td><td>Release of excitatory neurotransmitters (glutamate, substance P) from primary afferent terminals</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Vascular mechanisms</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>SCS causes vasodilatation in the stimulated dermatomal segments</td></tr><tr><td>Proposed mechanisms: antidromic activation of primary afferents releasing vasoactive peptides (CGRP) and nitric oxide, alongside suppression of sympathetic vasoconstrictor tone</td></tr><tr><td>This underlies the benefit of SCS in ischaemic pain &mdash; refractory angina, peripheral vascular disease, critical limb ischaemia &mdash; distinct from its neuropathic pain applications</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Newer stimulation paradigms</div><p style=\"margin:0 0 8px;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Mechanistically distinct from conventional tonic SCS:</p><table style=\"margin:0\"><tr><th>Paradigm</th><th>Proposed mechanism</th></tr><tr><td>High-frequency SCS (e.g. 10&nbsp;kHz)</td><td>Paraesthesia-free; does not rely on gate control in the same way &mdash; possibly depolarisation blockade of dorsal horn wide-dynamic-range neurons</td></tr><tr><td>Burst SCS</td><td>Bursts of high-frequency pulses preferentially engaging the medial (affective) pain pathway via the anterior cingulate cortex and thalamus; also paraesthesia-free</td></tr><tr><td>Differential Targeted Multiplex (DTM)</td><td>Possibly targets the neuro-immune pathway by altering glial&ndash;neuronal interaction and gene expression</td></tr><tr><td>Dorsal root ganglion (DRG) stimulation</td><td>Targets the DRG directly rather than the dorsal columns; suited to focal / discrete pain distributions (e.g. CRPS of one limb region)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ta159'',''NICE TA159 &mdash; Spinal Cord Stimulation'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE TA159 &mdash; Spinal Cord Stimulation\n</button></div></div>\n</div></div>","relevantReading":[{"label":"Spinal Cord Stimulation","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30097-5/fulltext"},{"label":"Advances in Spinal Cord Stimulation","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00087-3/fulltext"},{"label":"Spinal cord stimulators and implications for anaesthesia","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(20)30030-5/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_drg_stimulation_001', 'MTF', '{"dateAdded":"2026-09-07","rotationIndex":95,"stem":"Regarding dorsal root ganglion (DRG) stimulation:","choices":["It cannot be used for dermatomal or focal pain distributions","It cannot cause vasodilatation","It typically uses a stimulation frequency of 20–60 Hz","It is useful for complex regional pain syndrome (CRPS)","It produces analgesia via mechanisms identical to tonic spinal cord stimulation"],"correct":[false,false,true,true,false],"explanation":"<p>DRG stimulation is targeted neuromodulation of the dorsal root ganglion itself rather than the dorsal columns, giving precise, position-stable coverage of a single dermatome.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; DRG stimulation is, if anything, particularly well suited to focal, discrete dermatomal pain (e.g. groin, foot, chest wall), because targeting the ganglion for the affected dermatome gives precise, stable coverage that dorsal column stimulation struggles to hold in areas prone to positional variation.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; DRG stimulation can produce vasodilatation by mechanisms similar to conventional SCS (antidromic release of CGRP and nitric oxide), and may help some vascular / ischaemic pain presentations.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; DRG stimulation typically uses a low frequency of around 20&ndash;60&nbsp;Hz &mdash; lower than conventional tonic SCS &mdash; reflecting the electrode''s proximity to a sensitive target.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; CRPS confined to a specific limb region is a classic indication, where precise anatomical targeting outperforms the broader coverage pattern of dorsal column stimulation.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> &mdash; The mechanism is not identical to tonic SCS. Although there is overlap, DRG stimulation acts directly on the ganglion &mdash; which contains the cell bodies of primary sensory afferents &mdash; modulating first-order neuron transmission before the dorsal horn, rather than relying on the dorsal column-based gate control mechanism.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Dorsal Root Ganglion (DRG) Stimulation</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">DRG stimulation is a form of targeted neuromodulation that stimulates the dorsal root ganglion directly, rather than the dorsal columns of the spinal cord, giving a distinct anatomical and mechanistic approach compared with conventional SCS.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomical target &amp; rationale</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>The DRG houses the cell bodies of primary sensory afferent neurons for a single dermatome / spinal level &mdash; a discrete, reliably localisable target</td></tr><tr><td>Because each DRG maps to a specific dermatome, coverage is stable and does not shift much with patient position, unlike dorsal column SCS where paraesthesia coverage can move with posture</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Proposed mechanisms</div><table style=\"margin:0\"><tr><th>Mechanism</th></tr><tr><td>Modulation of hyperexcitable sensory neuron cell bodies within the ganglion, reducing aberrant / ectopic firing that drives neuropathic pain</td></tr><tr><td>Overlap with conventional SCS &mdash; antidromic activation releasing vasoactive peptides (CGRP, nitric oxide) and causing vasodilatation</td></tr><tr><td>Modulation of transmission at the first-order sensory neuron, before signals reach the dorsal horn &mdash; potentially more targeted suppression of pathological signalling than dorsal column approaches</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Stimulation parameters</div><table style=\"margin:0\"><tr><th>Parameter</th><th>Value</th></tr><tr><td>Frequency</td><td>20&ndash;60&nbsp;Hz &mdash; lower than conventional tonic dorsal column SCS, far lower than 10&nbsp;kHz high-frequency paradigms</td></tr><tr><td>Pulse width</td><td>200&ndash;500&nbsp;microseconds (as for tonic conventional SCS)</td></tr><tr><td>Amplitude</td><td>Typically lower than dorsal column SCS &mdash; the electrode sits close to the sensitive ganglion target</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical indications</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Focal, discrete neuropathic pain hard to capture with conventional SCS &mdash; groin / genital, foot, chest wall pain</td></tr><tr><td>Complex regional pain syndrome (CRPS) affecting a specific limb region</td></tr><tr><td>Post-herniorrhaphy / post-surgical focal neuropathic pain</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">DRG vs conventional SCS</div><table style=\"margin:0\"><tr><th>Consideration</th><th>DRG stimulation</th></tr><tr><td>Amplitude</td><td>Generally lower &mdash; may give a more favourable side-effect and battery-longevity profile in selected patients</td></tr><tr><td>Positional stability</td><td>Less dependent on patient position for consistent paraesthesia coverage</td></tr><tr><td>Lead placement</td><td>Technically more demanding &mdash; within the neuroforamen at the level of the DRG, versus standard epidural dorsal column placement</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Best Practices for Dorsal Root Ganglion Stimulation for Chronic Pain (ASPN guidelines)","source":"PMC · NCBI","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10024474/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_statistics_cv_sem_001', 'MTF', '{"dateAdded":"2026-09-07","rotationIndex":96,"stem":"Regarding statistics and data in clinical research:","choices":["A change in concentration from 1 nmol/L to 1.09 nmol/L, with an assay coefficient of variation of 5%, is likely to represent a real difference rather than assay variability","In a normal distribution, approximately 95% of values lie within 2 standard deviations of the mean","A p-value of <0.05 provides reasonable evidence to reject the null hypothesis","Pain scales such as the numerical rating scale represent ordinal data","The standard error of the mean is the standard deviation divided by the square root of the sample size"],"correct":[false,true,true,true,true],"explanation":"<p>These statements cover common descriptive and inferential statistics themes tested in the exam.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; The coefficient of variation (CV) describes relative dispersion around the mean and reflects a test''s <em>precision</em>, not its accuracy. A CV of 5% means the assay''s own measurement variability is about 5% of the value at that concentration. Going from 1 to 1.09&nbsp;nmol/L is only a 9% change &mdash; within roughly two CVs of the assay''s inherent variability &mdash; so it is more likely measurement noise than a genuine biological difference.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; In a Gaussian distribution about 68% of values lie within 1 SD, 95% within 2 SD, and 99.7% within 3 SD of the mean.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; p&nbsp;&lt;&nbsp;0.05 is the conventional threshold for statistical significance: less than a 5% probability that a result this extreme would occur by chance if the null hypothesis were true. It indicates statistical, not clinical, significance.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Numerical and verbal rating scales are ordinal: the values have a meaningful rank order, but the intervals between them cannot be assumed equal (the step from 2 to 3 is not necessarily the same magnitude as 8 to 9).</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; SEM = SD / &radic;n. Unlike the SD, which describes the spread of individual data points within the sample, the SEM estimates the precision of the sample mean and falls as sample size rises (you must quadruple n to halve the SEM).</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_statistics_diagnostic_tests_001', 'MTF', '{"dateAdded":"2026-09-07","rotationIndex":97,"stem":"Regarding diagnostic tests and statistical methods:","choices":["Low specificity is associated with a high false positive rate","The Mann–Whitney U test is a parametric test","The Chi-squared test is used for parametric data","Sensitivity is the proportion of true positives correctly identified by a test","Positive predictive value depends on the prevalence of the condition in the population tested"],"correct":[true,false,false,true,true],"explanation":"<p>These statements cover diagnostic test performance and the choice of statistical test.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; Specificity is the ability of a test to correctly identify those without the condition (true negatives). Low specificity means many unaffected people are misclassified as positive &mdash; a high false positive rate.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; The Mann&ndash;Whitney U test is non-parametric, comparing two independent groups when data are ordinal or not normally distributed. Its parametric equivalent is the unpaired t-test.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> &mdash; The Chi-squared test is a non-parametric test for association between categorical (nominal) variables. Normally distributed continuous data are analysed with the t-test or ANOVA.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Sensitivity is the proportion of people with the condition who test positive (true positive rate). A highly sensitive test has few false negatives and is useful for ruling out disease when negative (SnNout).</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Positive predictive value &mdash; the probability that a positive result is a true positive &mdash; falls as prevalence falls: even a highly sensitive and specific test has a low PPV in a low-prevalence population, because false positives outnumber true positives when the condition is rare.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;

-- link each new question to its (single) category
insert into question_categories (question_id, category_id)
  select 'q_mtf_scs_mechanism_001', id from categories where name = 'Physiology'
  on conflict do nothing;
insert into question_categories (question_id, category_id)
  select 'q_mtf_drg_stimulation_001', id from categories where name = 'Clinical Pain'
  on conflict do nothing;
insert into question_categories (question_id, category_id)
  select 'q_mtf_statistics_cv_sem_001', id from categories where name = 'Physics & Clinical Measurement'
  on conflict do nothing;
insert into question_categories (question_id, category_id)
  select 'q_mtf_statistics_diagnostic_tests_001', id from categories where name = 'Physics & Clinical Measurement'
  on conflict do nothing;
